import{_ as o,P as s,d as i,e as r,x as t,q as n}from"./chunks/framework.BRr8VP3a.js";const g=JSON.parse('{"title":"Part 16 Governance","description":"","frontmatter":{"title":"Part 16 Governance","xkChars":0,"xkWords":7895,"xkLessons":{"16.23":{"title":"Human oversight needs a real path to change the action","lead":"A review click is insufficient if evidence, time, capability, or an effective veto is missing.","explanation":["Oversight requires access to evidence, counterevidence, and uncertainty; relevant capability; time before the action; and a tolerable workload. The reviewer must be able to reject, modify, or pause. Those signals must reach the actuator soon enough to change what happens.","Evaluate more than the number of overrides. Can correct recommendations be appropriately adopted, incorrect ones stopped, unprompted problems detected, and affected people’s corrections acted on? More overrides are not always better, and total agreement is not proof of reliability.","For narrow operations faster than case-by-case human judgment, machine-checkable constraints and minimal permissions may be studied. This does not put all responsibility on a final click: target selection, omitted constraints, anomaly handling, and remedy still need responsible parties. A candidate must not become an observed fact merely because software passes it onward."],"distinctions":[{"leftTitle":"A nominal review step","leftText":"The interface records a click or acknowledgment.","rightTitle":"Effective oversight","rightText":"The reviewer has the conditions and actual ability to alter execution."}],"teachingExamples":[{"title":"A rejection arrives after execution","text":"Suppose a user presses reject but the backend task is already irreversible. The interface recorded a refusal; it did not provide a timely veto over that action.","assumptions":"Hypothetical software behavior; no actual product is assessed.","boundary":"The example does not establish which legal or organizational duty applies."}],"boundaries":["AI output cannot independently certify real-world safety, consent, or authorization.","Personality hypotheses do not license clinical diagnosis or unauthorized discriminatory scoring."],"questionAnswers":[{"question":"Does a high override rate prove good oversight?","answer":"No. Review quality depends on appropriately accepting correct advice, stopping errors, detecting other problems, and enabling correction.","basis":"Theory v2, §16.23, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"16.23","startLine":3713,"endLine":3720}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-16#section-16-23","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§16.23; English reading edition, lines 3713–3720","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"16.24":{"title":"Replace a model when the comparison warrants it","lead":"Compare judgment quality and total burden under fixed tasks and a serious alternative.","explanation":["A framework needs a retirement and replacement path. If a simpler method consistently performs better on the relevant explanation, foresight, protection, and accessibility tasks, hand over the necessary records, failures, unresolved claims, and responsibilities rather than preserving the model’s status for its own sake.","Fix the task, materials, input cutoff, resources, and evaluation method. Keep a sufficiently strong domain method and accurate source retrieval as comparators. Examine errors, omissions, inappropriate nonanswers, time, disclosure, and maintenance work separately. More files, characters, or accepted candidates do not measure practical benefit.","A textual adoption is an editorial fact. A successful build is an engineering fact. Running the changed package, producing an adequate answer, and benefiting a real task have different endpoints. When theory, software, and materials change together, a comparison can assess the combination but cannot assign all improvement to one sentence or one packaging choice."],"distinctions":[{"leftTitle":"A verified artifact change","leftText":"Evidence that text or software actually changed.","rightTitle":"Demonstrated task benefit","rightText":"Evidence from an appropriate comparison of outcomes and burdens."}],"teachingExamples":[{"title":"A new version produces more reports","text":"Suppose a revised tool writes twice as many reports. Without a fixed task comparison, this establishes output volume, not improved decisions or lower reader burden.","assumptions":"Hypothetical software comparison.","boundary":"A local improvement can still be preserved when another dimension worsens; neither should be hidden."}],"boundaries":["Retirement does not erase unresolved harm or responsibility records.","Internal checks and accurate hashes do not establish external effectiveness."],"questionAnswers":[{"question":"If no comparative study exists, should the framework be declared equivalent or useless?","answer":"No. Absence of comparison supports neither superiority nor equivalence nor uselessness. State the untested claim and retain existing bounded evidence.","basis":"Theory v2, §16.24, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"16.24","startLine":3721,"endLine":3728}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-16#section-16-24","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§16.24; English reading edition, lines 3721–3728","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-16.md","filePath":"en/theory/part-16.md"}'),c={name:"en/theory/part-16.md"};function d(l,e,p,u,h,m){const a=s("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=t("",1)),n(a,{section:"16.23"}),e[1]||(e[1]=t("",1)),n(a,{section:"16.24"}),e[2]||(e[2]=t("",3))])}const b=o(c,[["render",d]]);export{g as __pageData,b as default};
